@layer theme {
  :root, :host { --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace; --default-font-family: var(--font-sans); --default-mono-font-family: var(--font-mono); }
}
@layer base {
  *, ::after, ::before, ::backdrop { box-sizing: border-box; border: 0px solid; margin: 0px; padding: 0px; }
  ::file-selector-button { box-sizing: border-box; border: 0px solid; margin: 0px; padding: 0px; }
  html, :host { text-size-adjust: 100%; tab-size: 4; line-height: 1.5; font-family: var(--default-font-family,-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"); font-feature-settings: var(--default-font-feature-settings,normal); font-variation-settings: var(--default-font-variation-settings,normal); -webkit-tap-highlight-color: transparent; }
  hr { height: 0px; color: inherit; border-top-width: 1px; }
  abbr:where([title]) { text-decoration: underline dotted; }
  h1, h2, h3, h4, h5, h6 { font-size: inherit; font-weight: inherit; }
  a { color: inherit; text-decoration: inherit; }
  b, strong { font-weight: bolder; }
  code, kbd, samp, pre { font-family: var(--default-mono-font-family,ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace); font-feature-settings: var(--default-mono-font-feature-settings,normal); font-variation-settings: var(--default-mono-font-variation-settings,normal); font-size: 1em; }
  small { font-size: 80%; }
  sub, sup { vertical-align: baseline; font-size: 75%; line-height: 0; position: relative; }
  sub { bottom: -0.25em; }
  sup { top: -0.5em; }
  table { text-indent: 0px; border-color: inherit; border-collapse: collapse; }
  progress { vertical-align: baseline; }
  summary { display: list-item; }
  ol, ul, menu { list-style: none; }
  img, svg, video, canvas, audio, iframe, embed, object { vertical-align: middle; display: block; }
  img, video { max-width: 100%; height: auto; }
  button, input, select, optgroup, textarea { font: inherit; letter-spacing: inherit; color: inherit; opacity: 1; background-color: rgba(0, 0, 0, 0); border-radius: 0px; }
  ::file-selector-button { font: inherit; letter-spacing: inherit; color: inherit; opacity: 1; background-color: rgba(0, 0, 0, 0); border-radius: 0px; }
  :where(select:is([multiple], [size])) optgroup { font-weight: bolder; }
  :where(select:is([multiple], [size])) optgroup option { padding-inline-start: 20px; }
  ::file-selector-button { margin-inline-end: 4px; }
  ::placeholder { opacity: 1; }
  @supports (not ((-webkit-appearance:-apple-pay-button))) or (contain-intrinsic-size:1px) {
  ::placeholder { color: currentcolor; }
  @supports (color:color-mix(in lab, red, red)) {
  ::placeholder { color: color-mix(currentcolor, transparent); }
}
}
  textarea { resize: vertical; }
  ::-webkit-search-decoration { appearance: none; }
  ::-webkit-date-and-time-value { min-height: 1lh; text-align: inherit; }
  ::-webkit-datetime-edit { display: inline-flex; }
  ::-webkit-datetime-edit-fields-wrapper { padding: 0px; }
  ::-webkit-datetime-edit { padding-block: 0px; }
  ::-webkit-datetime-edit-year-field { padding-block: 0px; }
  ::-webkit-datetime-edit-month-field { padding-block: 0px; }
  ::-webkit-datetime-edit-day-field { padding-block: 0px; }
  ::-webkit-datetime-edit-hour-field { padding-block: 0px; }
  ::-webkit-datetime-edit-minute-field { padding-block: 0px; }
  ::-webkit-datetime-edit-second-field { padding-block: 0px; }
  ::-webkit-datetime-edit-millisecond-field { padding-block: 0px; }
  ::-webkit-datetime-edit-meridiem-field { padding-block: 0px; }
  ::-webkit-calendar-picker-indicator { line-height: 1; }
  button, input:where([type="button"], [type="reset"], [type="submit"]) { appearance: button; }
  ::file-selector-button { appearance: button; }
  ::-webkit-inner-spin-button { height: auto; }
  ::-webkit-outer-spin-button { height: auto; }
  [hidden]:where(:not([hidden="until-found"])) { display: none !important; }
}
@layer components;
@layer utilities {
  .fixed { position: fixed; }
  .block { display: block; }
}
@font-face { font-family: Manrope; src: url("manrope-variable.ttf") format("truetype"); font-style: normal; font-weight: 200 800; font-display: swap; }
:root { --lightningcss-light: ; --lightningcss-dark: initial; color-scheme: dark; --bg: #0b0d11; --surface: #12151c; --raised: #191e27; --border: #282e39; --text: #f5f7fa; --muted: #a5adbd; --quiet: #8e98ab; --mint: #a3f5c5; --mint-ink: #11291b; --amber: #f5cf8e; --red: #ffb2ad; --radius: 15px; --font-sans: "Manrope","Segoe UI",sans-serif; --font-mono: "IBM Plex Mono","Cascadia Mono",monospace; }
* { box-sizing: border-box; }
html, body { background: var(--bg); min-height: 100%; color: var(--text); font-family: var(--font-sans); margin: 0px; }
body { font-size: 14px; line-height: 1.55; }
button, input, a { -webkit-tap-highlight-color: transparent; }
button, input { font: inherit; }
button, a { touch-action: manipulation; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: 0.5; }
a { color: inherit; text-underline-offset: 4px; text-decoration: none; }
button, input { color: inherit; }
button:focus-visible, a:focus-visible { outline: 2px solid var(--mint); outline-offset: 5px; }
input:focus-visible { outline: 2px solid var(--mint); outline-offset: 2px; }
::selection { color: rgb(17, 41, 27); background: rgb(163, 245, 197); }
* { scrollbar-color: #3b4554 var(--bg); scrollbar-width: thin; }
input { caret-color: var(--mint); }
h1, h2, h3, p { margin: 0px; }
h1, h2 { text-wrap: balance; }
code { font-family: var(--font-mono); font-variant-numeric: tabular-nums; font-size: 0.87em; }
svg { flex-shrink: 0; }
button { transition: background 0.15s ease-out, border-color 0.15s ease-out, opacity 0.15s ease-out; }
button:not(:disabled):active { transform: translateY(1px); }
.app-shell { min-height: 100dvh; display: flex; }
.skip-link { z-index: 20; background: var(--mint); color: var(--mint-ink); border-radius: 8px; padding: 12px 16px; position: fixed; top: -70px; left: 18px; }
.skip-link:focus { top: 14px; }
.sidebar { background: rgb(14, 17, 23); border-right: 1px solid rgb(35, 40, 51); flex-direction: column; width: 226px; padding: 31px 20px 20px; display: flex; position: fixed; inset: 0px auto 0px 0px; }
.brand { letter-spacing: -0.8px; align-items: center; gap: 9px; font-size: 23px; font-weight: 750; line-height: 1; display: flex; }
.brand-mark { background: var(--mint); color: rgb(19, 42, 28); border-radius: 8px; place-items: center; width: 31px; height: 31px; display: grid; }
.brand-dot { color: var(--mint); margin-left: -8px; }
.workspace-label { letter-spacing: 1.8px; color: var(--quiet); margin: 54px 12px 14px; font-size: 12px; font-weight: 650; }
.nav-item { border-radius: 8px; align-items: center; gap: 10px; padding: 11px 12px; font-size: 14px; font-weight: 600; display: flex; }
.nav-item.active { color: rgb(196, 247, 217); background: rgb(27, 40, 37); }
.nav-item > svg:last-child { color: var(--mint); margin-left: auto; }
.sidebar-bottom { margin-top: auto; padding-top: 80px; }
.test-notice { color: rgb(219, 226, 236); padding: 14px 11px; font-size: 13px; }
.status-dot { background: var(--mint); border-radius: 100%; width: 6px; height: 6px; margin-right: 7px; display: inline-block; }
.network-name { color: var(--quiet); margin: 5px 0px 0px 14px; font-size: 12px; display: block; }
.help-button { border-right: 0px; border-bottom: 0px; border-left: 0px; border-image: none; border-top: 1px solid var(--border); width: 100%; color: var(--muted); text-align: left; background: 0px 0px; align-items: center; gap: 9px; padding: 18px 10px 8px; font-size: 13px; display: flex; }
.help-button > svg:last-child { margin-left: auto; transition: transform 0.15s; }
.rotate { transform: rotate(90deg); }
.help-content { color: var(--muted); padding: 10px; font-size: 13px; line-height: 1.8; }
.workspace { width: calc(100% - 226px); margin-left: 226px; }
.topbar { border-bottom: 1px solid rgb(35, 40, 51); justify-content: space-between; align-items: center; height: 76px; padding: 0px 44px; display: flex; }
.breadcrumb { color: var(--quiet); align-items: center; gap: 14px; font-size: 13px; display: flex; }
.breadcrumb > span { color: rgb(214, 220, 229); }
.topbar-right { align-items: center; gap: 18px; display: flex; }
.network-chip { color: rgb(185, 194, 208); border: 1px solid rgb(50, 58, 71); border-radius: 6px; padding: 6px 10px; font-size: 12px; }
.network-chip .status-dot { width: 5px; height: 5px; }
.icon-button { width: 44px; height: 44px; color: var(--muted); background: 0px 0px; border: 0px; border-radius: 6px; place-items: center; display: grid; }
.icon-button:not(:disabled):hover { color: var(--text); background: rgb(36, 44, 53); }
.main-content { max-width: 1260px; margin: 0px auto; padding: 47px 44px 0px; }
.main-content:focus { outline: none; }
.page-heading { justify-content: space-between; align-items: center; gap: 20px; margin-bottom: 37px; display: flex; }
h1 { letter-spacing: -1.15px; font-size: 34px; font-weight: 620; line-height: 1.2; }
.heading-dot { color: var(--mint); }
.page-heading p { color: var(--muted); margin-top: 10px; font-size: 13px; }
.environment-tag { color: rgb(182, 192, 208); white-space: nowrap; border: 1px solid rgb(61, 67, 80); border-radius: 5px; padding: 5px 9px; font-size: 12px; }
.setup-layout { grid-template-columns: minmax(0px, 1fr) 270px; align-items: start; gap: 38px; display: grid; }
.setup-work { min-width: 0px; }
.setup-steps { justify-content: space-between; gap: 12px; margin: 0px 0px 27px; padding: 0px; list-style: none; display: flex; }
.setup-steps li { flex: 1 1 0%; align-items: center; gap: 9px; min-width: 0px; display: flex; position: relative; }
.step-symbol { color: rgb(177, 189, 205); border: 1px solid rgb(58, 67, 81); border-radius: 100%; flex-shrink: 0; place-items: center; width: 25px; height: 25px; font-size: 13px; display: grid; }
.step-title { color: var(--muted); white-space: nowrap; font-size: 12px; font-weight: 600; line-height: 1.4; display: block; }
.step-detail { display: none; }
.setup-steps .current .step-symbol { background: var(--mint); color: var(--mint-ink); border-color: var(--mint); font-weight: 750; }
.setup-steps .current .step-title { color: var(--text); }
.setup-steps .complete .step-symbol { color: var(--mint); background: rgb(26, 48, 38); border-color: rgb(53, 84, 68); }
.setup-steps .complete .step-title { color: rgb(194, 214, 206); }
.step-connector { background: rgb(52, 60, 73); width: 16px; height: 1px; margin-left: auto; }
.setup-panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 33px; }
.panel-topline { justify-content: space-between; align-items: center; margin-bottom: 30px; display: flex; }
.surface-icon { color: rgb(183, 244, 209); background: rgb(32, 48, 42); border-radius: 13px; place-items: center; width: 48px; height: 48px; display: grid; }
.private-label { color: rgb(154, 166, 184); align-items: center; gap: 5px; font-size: 12px; display: flex; }
.wallet-panel h2 { letter-spacing: -1.1px; font-size: 33px; font-weight: 620; line-height: 1.22; }
.panel-description { color: var(--muted); max-width: 350px; margin-top: 18px; font-size: 14px; line-height: 1.9; }
.primary-button { background: var(--mint); color: var(--mint-ink); white-space: nowrap; border: 1px solid rgba(0, 0, 0, 0); border-radius: 7px; justify-content: center; align-items: center; gap: 9px; min-height: 42px; padding: 11px 16px; font-size: 13px; font-weight: 750; display: inline-flex; }
.primary-button:not(:disabled):hover { background: rgb(193, 251, 217); }
.connect-button { justify-content: flex-start; width: 100%; min-height: 48px; margin-top: 31px; padding: 13px 17px; font-size: 14px; }
.connect-button > svg:last-child { margin-left: auto; }
.signature-note { color: rgb(160, 172, 189); align-items: flex-start; gap: 10px; margin-top: 21px; font-size: 12px; line-height: 1.9; display: flex; }
.signature-note > svg { color: rgb(149, 169, 153); margin-top: 2px; }
.signature-note strong { color: rgb(196, 205, 217); font-weight: 400; }
.network-footnote { border-top: 1px solid var(--border); color: rgb(181, 193, 208); align-items: center; gap: 9px; margin-top: 30px; padding-top: 22px; font-size: 12px; display: flex; }
.network-footnote > span:nth-child(2) > span { color: rgb(149, 161, 180); margin-top: 2px; font-size: 11px; display: block; }
.network-footnote > svg { color: rgb(149, 161, 180); margin-left: auto; }
.small-network-mark { color: rgb(24, 30, 40); background: rgb(236, 239, 244); border-radius: 100%; place-items: center; width: 29px; height: 29px; font-size: 14px; font-weight: 800; display: grid; }
.setup-context { padding-top: 9px; }
.context-introduction { padding: 24px 0px 0px; }
.context-symbol { width: 48px; height: 48px; color: var(--mint); border: 1px solid rgb(59, 75, 67); border-radius: 100%; place-items: center; margin-bottom: 24px; display: grid; }
.context-introduction h2 { letter-spacing: -0.7px; font-size: 25px; font-weight: 560; line-height: 1.27; }
.context-introduction > p { color: var(--muted); max-width: 250px; margin-top: 16px; font-size: 13px; line-height: 1.9; }
.trust-list { margin: 26px 0px 0px; padding: 0px; list-style: none; }
.trust-list li { color: rgb(165, 177, 195); gap: 10px; margin-bottom: 18px; font-size: 12px; line-height: 1.9; display: flex; }
.trust-list li > svg { color: rgb(159, 223, 189); margin-top: 3px; }
.trust-list strong { color: rgb(215, 223, 233); margin-bottom: 3px; font-size: 13px; font-weight: 550; display: block; }
.test-boundary { border-top: 1px solid var(--border); color: rgb(149, 163, 183); align-items: flex-start; gap: 9px; margin-top: 26px; padding-top: 20px; font-size: 12px; line-height: 1.9; display: flex; }
.test-boundary > svg { color: rgb(167, 180, 197); margin-top: 3px; }
.workspace-footer { color: rgb(148, 160, 179); border-top: 1px solid rgb(37, 44, 55); justify-content: space-between; align-items: center; gap: 18px; margin-top: 43px; padding: 21px 0px 25px; font-size: 11px; display: flex; }
.workspace-footer > span:last-child { align-items: center; gap: 6px; display: flex; }
.footer-separator { color: rgb(103, 116, 135); margin: 0px 10px; }
.loading-state { text-align: center; flex-direction: column; justify-content: center; align-items: center; gap: 14px; min-height: 405px; display: flex; }
.loading-state > svg { color: var(--mint); }
.loading-state h2 { letter-spacing: -0.4px; font-size: 20px; }
.loading-state p { color: var(--muted); font-size: 14px; }
.spin { animation: 1s linear 0s infinite normal none running spin; }
@keyframes spin { 
  100% { transform: rotate(360deg); }
}
.notice { border: 1px solid; border-radius: 9px; align-items: flex-start; gap: 10px; margin-bottom: 19px; padding: 14px; font-size: 13px; line-height: 1.8; display: flex; }
.notice > svg { margin-top: 2px; }
.notice strong { font-size: 14px; display: block; }
.notice p { margin: 1px 0px 0px; }
.notice-error { color: rgb(245, 195, 187); background: rgb(43, 28, 29); border-color: rgb(92, 57, 59); }
.notice-success { color: rgb(191, 232, 210); background: rgb(23, 40, 31); border-color: rgb(49, 77, 60); }
.dismiss-button { color: inherit; background: 0px 0px; border: 0px; margin-left: auto; padding: 3px; }
.text-button { color: inherit; font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; text-underline-offset: 3px; background: 0px 0px; border: 0px; align-items: center; gap: 7px; padding: 7px 0px 0px; font-weight: 650; text-decoration: underline; display: inline-flex; }
.section-heading { justify-content: space-between; align-items: flex-start; gap: 18px; margin-bottom: 24px; display: flex; }
.section-heading h2 { letter-spacing: -0.7px; font-size: 23px; font-weight: 580; }
.section-heading p { color: var(--muted); margin-top: 7px; font-size: 13px; }
.small-icon { color: rgb(159, 174, 193); margin-top: 4px; }
.identity-line { border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); color: var(--muted); flex-wrap: wrap; align-items: center; gap: 7px; margin-bottom: 23px; padding: 14px 0px; font-size: 12px; display: flex; }
.verified-icon { color: var(--mint); background: rgb(33, 54, 43); border-radius: 100%; place-items: center; width: 20px; height: 20px; display: grid; }
.identity-line code { color: rgb(211, 224, 218); margin-left: 3px; }
.identity-verified { color: rgb(185, 228, 204); margin-left: auto; font-size: 11px; }
.form-field { flex-direction: column; gap: 8px; margin-bottom: 21px; display: flex; }
.form-field label { color: rgb(217, 224, 234); font-size: 13px; font-weight: 550; }
.form-field input { background: rgb(14, 18, 25); border: 1px solid rgb(58, 69, 84); border-radius: 7px; width: 100%; min-height: 44px; padding: 11px 12px; font-size: 14px; line-height: 1.6; transition: border-color 0.15s; }
.form-field input::placeholder { color: rgb(137, 150, 170); }
.form-field input[aria-invalid="true"] { border-color: rgb(183, 104, 100); }
.field-hint { color: rgb(155, 167, 186); font-size: 12px; line-height: 1.8; }
.field-error { color: var(--red); font-size: 12px; }
.form-footer { flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 14px; padding-top: 3px; display: flex; }
.form-footer > span { color: rgb(155, 168, 186); font-size: 11px; }
.settlement-panel { margin-top: 19px; padding-top: 28px; padding-bottom: 28px; }
.settlement-panel .section-heading { margin-bottom: 20px; }
.wallet-address { background: rgb(13, 18, 24); border: 1px solid rgb(52, 64, 77); border-radius: 7px; align-items: center; gap: 10px; padding: 13px 12px; display: flex; }
.wallet-address code { overflow-wrap: anywhere; color: rgb(204, 215, 228); flex: 1 1 0%; font-size: 12px; line-height: 1.9; }
.wallet-address > a { color: rgb(167, 185, 205); display: flex; }
.ownership-line { color: rgb(187, 220, 201); align-items: center; gap: 7px; margin-top: 12px; font-size: 11px; display: flex; }
.ownership-line > span { color: rgb(154, 169, 189); margin-left: auto; font-size: 10px; }
.settlement-description { color: var(--muted); margin-top: 20px; font-size: 12px; line-height: 1.9; }
.secondary-button { color: rgb(199, 213, 229); background: rgb(25, 33, 42); border: 1px solid rgb(71, 84, 101); border-radius: 7px; justify-content: center; align-items: center; gap: 8px; min-height: 38px; margin-top: 15px; padding: 9px 12px; font-size: 12px; font-weight: 600; display: inline-flex; }
.secondary-button:not(:disabled):hover { background: rgb(37, 48, 60); border-color: rgb(100, 117, 139); }
.wallet-change-note { color: rgb(237, 211, 170); background: rgb(42, 37, 29); border: 1px solid rgb(107, 84, 57); border-radius: 7px; margin-bottom: 22px; padding: 12px; font-size: 13px; line-height: 1.9; }
.wallet-change-note code { white-space: nowrap; }
.screening-summary { border-top: 1px solid var(--border); margin-top: 26px; padding-top: 21px; }
.screening-title { color: rgb(199, 212, 228); align-items: center; gap: 8px; display: flex; }
.screening-title h3 { font-size: 13px; font-weight: 600; }
.screening-title > .icon-button { margin-left: auto; }
.screening-allowed .screening-title > svg { color: var(--mint); }
.screening-held .screening-title > svg { color: var(--amber); }
.screening-badge { border-radius: 5px; margin: 12px 0px; padding: 5px 8px; font-size: 11px; font-weight: 650; display: inline-flex; }
.positive { color: rgb(184, 233, 201); background: rgb(32, 55, 42); }
.caution { color: rgb(241, 209, 155); background: rgb(48, 41, 31); }
.screening-summary > p { color: rgb(170, 183, 201); font-size: 12px; line-height: 1.9; }
.screening-summary dl { margin: 17px 0px; font-size: 11px; }
.screening-summary dl > div { justify-content: space-between; gap: 12px; line-height: 2.6; display: flex; }
.screening-summary dt { color: rgb(151, 165, 186); }
.screening-summary dd { text-align: right; color: rgb(193, 205, 221); margin: 0px; }
.screening-summary .coverage-note { color: rgb(150, 164, 185); font-size: 11px; line-height: 1.8; }
@media (min-width: 1500px) {
  .main-content { padding-top: 58px; }
  .setup-layout { grid-template-columns: minmax(0px, 620px) 280px; gap: 50px; }
  .setup-steps { margin-bottom: 30px; }
  .setup-panel { padding: 38px; }
  .step-detail { color: rgb(147, 160, 179); margin-top: 4px; font-size: 10px; display: block; }
  .step-title { font-size: 13px; }
}
@media (max-width: 1100px) {
  .sidebar { width: 198px; padding-left: 15px; padding-right: 15px; }
  .workspace { width: calc(100% - 198px); margin-left: 198px; }
  .topbar { padding: 0px 30px; }
  .main-content { padding-left: 30px; padding-right: 30px; }
  .setup-layout { grid-template-columns: minmax(0px, 1fr) 220px; gap: 28px; }
  .setup-panel { padding: 26px; }
  .step-title { font-size: 11px; }
  .step-symbol { width: 23px; height: 23px; }
  .setup-steps { gap: 8px; }
  .setup-steps li { gap: 6px; }
  .step-connector { display: none; }
  .context-introduction h2 { font-size: 23px; }
}
@media (max-width: 900px) {
  .sidebar { width: 176px; padding-left: 13px; padding-right: 13px; }
  .workspace { width: calc(100% - 176px); margin-left: 176px; }
  .brand { gap: 7px; font-size: 20px; }
  .brand-mark { width: 28px; height: 28px; }
  .nav-item { gap: 7px; padding-left: 10px; padding-right: 8px; font-size: 12px; }
  .workspace-label { margin-left: 10px; font-size: 11px; }
  .topbar { height: 68px; padding: 0px 25px; }
  .main-content { padding: 35px 25px 0px; }
  .page-heading { margin-bottom: 29px; }
  h1 { font-size: 29px; }
  .page-heading p { font-size: 14px; }
