.R9Buya_footer { color: rgb(142, 155, 174); border-top: 1px solid rgb(40, 46, 57); justify-content: space-between; align-items: center; gap: 15px; margin-top: 29px; padding: 22px 0px 30px; font-size: 10px; display: flex; }
