.R9Buya_loading, .R9Buya_unavailable { text-align: center; background: rgb(18, 21, 28); border: 1px solid rgb(40, 46, 57); border-radius: 15px; flex-direction: column; justify-content: center; align-items: center; gap: 15px; min-height: 385px; padding: 35px; display: flex; }
