overview.css:
@layer theme {
  :root, :host { --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace; --default-font-family: var(--font-sans); --default-mono-font-family: var(--font-mono); }
}
@layer base {
  *, ::after, ::before, ::backdrop { box-sizing: border-box; border: 0px solid; margin: 0px; padding: 0px; }
  ::file-selector-button { box-sizing: border-box; border: 0px solid; margin: 0px; padding: 0px; }
  html, :host { text-size-adjust: 100%; tab-size: 4; line-height: 1.5; font-family: var(--default-font-family,-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"); font-feature-settings: var(--default-font-feature-settings,normal); font-variation-settings: var(--default-font-variation-settings,normal); -webkit-tap-highlight-color: transparent; }
  hr { height: 0px; color: inherit; border-top-width: 1px; }
  abbr:where([title]) { text-decoration: underline dotted; }
  h1, h2, h3, h4, h5, h6 { font-size: inherit; font-weight: inherit; }
  a { color: inherit; text-decoration: inherit; }
  b, strong { font-weight: bolder; }
  code, kbd, samp, pre { font-family: var(--default-mono-font-family,ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace); font-feature-settings: var(--default-mono-font-feature-settings,normal); font-variation-settings: var(--default-mono-font-variation-settings,normal); font-size: 1em; }
  small { font-size: 80%; }
  sub, sup { vertical-align: baseline; font-size: 75%; line-height: 0; position: relative; }
  sub { bottom: -0.25em; }
  sup { top: -0.5em; }
  table { text-indent: 0px; border-color: inherit; border-collapse: collapse; }
  progress { vertical-align: baseline; }
  summary { display: list-item; }
  ol, ul, menu { list-style: none; }
  img, svg, video, canvas, audio, iframe, embed, object { vertical-align: middle; display: block; }
  img, video { max-width: 100%; height: auto; }
  button, input, select, optgroup, textarea { font: inherit; letter-spacing: inherit; color: inherit; opacity: 1; background-color: rgba(0, 0, 0, 0); border-radius: 0px; }
  ::file-selector-button { font: inherit; letter-spacing: inherit; color: inherit; opacity: 1; background-color: rgba(0, 0, 0, 0); border-radius: 0px; }
  :where(select:is([multiple], [size])) optgroup { font-weight: bolder; }
  :where(select:is([multiple], [size])) optgroup option { padding-inline-start: 20px; }
  ::file-selector-button { margin-inline-end: 4px; }
  ::placeholder { opacity: 1; }
  @supports (not ((-webkit-appearance:-apple-pay-button))) or (contain-intrinsic-size:1px) {
  ::placeholder { color: currentcolor; }
  @supports (color:color-mix(in lab, red, red)) {
  ::placeholder { color: color-mix(currentcolor, transparent); }
}
}
  textarea { resize: vertical; }
  ::-webkit-search-decoration { appearance: none; }
  ::-webkit-date-and-time-value { min-height: 1lh; text-align: inherit; }
  ::-webkit-datetime-edit { display: inline-flex; }
  ::-webkit-datetime-edit-fields-wrapper { padding: 0px; }
  ::-webkit-datetime-edit { padding-block: 0px; }
  ::-webkit-datetime-edit-year-field { padding-block: 0px; }
  ::-webkit-datetime-edit-month-field { padding-block: 0px; }
  ::-webkit-datetime-edit-day-field { padding-block: 0px; }
  ::-webkit-datetime-edit-hour-field { padding-block: 0px; }
  ::-webkit-datetime-edit-minute-field { padding-block: 0px; }
  ::-webkit-datetime-edit-second-field { padding-block: 0px; }
  ::-webkit-datetime-edit-millisecond-field { padding-block: 0px; }
  ::-webkit-datetime-edit-meridiem-field { padding-block: 0px; }
  ::-webkit-calendar-picker-indicator { line-height: 1; }
  button, input:where([type="button"], [type="reset"], [type="submit"]) { appearance: button; }
  ::file-selector-button { appearance: button; }
  ::-webkit-inner-spin-button { height: auto; }
  ::-webkit-outer-spin-button { height: auto; }
  [hidden]:where(:not([hidden="until-found"])) { display: none !important; }
}
@layer components;
@layer utilities {
  .fixed { position: fixed; }
  .block { display: block; }
}
@font-face { font-family: Manrope; src: url("manrope-variable.ttf") format("truetype"); font-style: normal; font-weight: 200 800; font-display: swap; }
:root { --lightningcss-light: ; --lightningcss-dark: initial; color-scheme: dark; --bg: #0b0d11; --surface: #12151c; --raised: #191e27; --border: #282e39; --text: #f5f7fa; --muted: #a5adbd; --quiet: #8e98ab; --mint: #a3f5c5; --mint-ink: #11291b; --amber: #f5cf8e; --red: #ffb2ad; --radius: 15px; --font-sans: "Manrope","Segoe UI",sans-serif; --font-mono: "IBM Plex Mono","Cascadia Mono",monospace; }
* { box-sizing: border-box; }
html, body { background: var(--bg); min-height: 100%; color: var(--text); font-family: var(--font-sans); margin: 0px; }
body { font-size: 14px; line-height: 1.55; }
button, input, a { -webkit-tap-highlight-color: transparent; }
button, input { font: inherit; }
button, a { touch-action: manipulation; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: 0.5; }
a { color: inherit; text-underline-offset: 4px; text-decoration: none; }
button, input { color: inherit; }
button:focus-visible, a:focus-visible { outline: 2px solid var(--mint); outline-offset: 5px; }
input:focus-visible { outline: 2px solid var(--mint); outline-offset: 2px; }
::selection { color: rgb(17, 41, 27); background: rgb(163, 245, 197); }
* { scrollbar-color: #3b4554 var(--bg); scrollbar-width: thin; }
input { caret-color: var(--mint); }
h1, h2, h3, p { margin: 0px; }
h1, h2 { text-wrap: balance; }
code { font-family: var(--font-mono); font-variant-numeric: tabular-nums; font-size: 0.87em; }
svg { flex-shrink: 0; }
button { transition: background 0.15s ease-out, border-color 0.15s ease-out, opacity 0.15s ease-out; }
button:not(:disabled):active { transform: translateY(1px); }
.app-shell { min-height: 100dvh; display: flex; }
.skip-link { z-index: 20; background: var(--mint); color: var(--mint-ink); border-radius: 8px; padding: 12px 16px; position: fixed; top: -70px; left: 18px; }
.skip-link:focus { top: 14px; }
.sidebar { background: rgb(14, 17, 23); border-right: 1px solid rgb(35, 40, 51); flex-direction: column; width: 226px; padding: 31px 20px 20px; display: flex; position: fixed; inset: 0px auto 0px 0px; }
.brand { letter-spacing: -0.8px; align-items: center; gap: 9px; font-size: 23px; font-weight: 750; line-height: 1; display: flex; }
.brand-mark { background: var(--mint); color: rgb(19, 42, 28); border-radius: 8px; place-items: center; width: 31px; height: 31px; display: grid; }
.brand-dot { color: var(--mint); margin-left: -8px; }
.workspace-label { letter-spacing: 1.8px; color: var(--quiet); margin: 54px 12px 14px; font-size: 12px; font-weight: 650; }
.nav-item { border-radius: 8px; align-items: center; gap: 10px; padding: 11px 12px; font-size: 14px; font-weight: 600; display: flex; }
.nav-item.active { color: rgb(196, 247, 217); background: rgb(27, 40, 37); }
.nav-item > svg:last-child { color: var(--mint); margin-left: auto; }
.sidebar-bottom { margin-top: auto; padding-top: 80px; }
.test-notice { color: rgb(219, 226, 236); padding: 14px 11px; font-size: 13px; }
.status-dot { background: var(--mint); border-radius: 100%; width: 6px; height: 6px; margin-right: 7px; display: inline-block; }
